package com.motionlayer.importer
import android.net.Uri
import androidx.activity.compose.rememberLauncherForActivityResult; import androidx.activity.result.contract.ActivityResultContracts; import androidx.compose.foundation.layout.*; import androidx.compose.material3.*; import androidx.compose.runtime.*; import androidx.compose.ui.Modifier; import androidx.compose.ui.unit.dp
@Composable fun ImportScreen(onCreate:(String,String)->Unit){ var uri by remember{ mutableStateOf<Uri?>(null)}; var ratio by remember{ mutableStateOf("9:16")}; val pick= rememberLauncherForActivityResult(ActivityResultContracts.GetContent()){ uri=it }; Column(Modifier.fillMaxSize().padding(24.dp), verticalArrangement=Arrangement.spacedBy(16.dp)){ Text("Create MotionLayer Project", style=MaterialTheme.typography.headlineSmall); Button({pick.launch("video/*")}){Text(if(uri==null)"Pick video from device" else "Video selected")}; Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){ listOf("9:16","16:9","1:1").forEach{ Button({ratio=it}, enabled=ratio!=it){Text(it)} } }; Button(enabled=uri!=null,onClick={onCreate(uri.toString(),ratio)}){Text("Create project")} } }
